"use strict";

const { SMTPServer } = require("smtp-server");

const port = Number(process.env.SMTP_PORT || 1025);
const server = new SMTPServer({
    authOptional: true,
    disabledCommands: ["STARTTLS"],
    onData(stream, session, callback) {
        const chunks = [];
        stream.on("data", (chunk) => chunks.push(chunk));
        stream.on("error", callback);
        stream.on("end", () => {
            const rawMessage = Buffer.concat(chunks).toString("utf8");
            console.log(JSON.stringify({
                event: "smtp-message-accepted",
                remoteAddress: session.remoteAddress,
                mailFrom: session.envelope.mailFrom.address,
                rcptTo: session.envelope.rcptTo.map((recipient) => recipient.address),
                rawMessage,
            }));
            callback();
        });
    },
});

server.on("error", (error) => {
    console.error("local SMTP sink error:", error.message);
    process.exitCode = 1;
});

server.listen(port, "127.0.0.1", () => {
    console.log(`local SMTP sink listening on 127.0.0.1:${port}`);
});

process.on("SIGTERM", () => {
    server.close(() => process.exit());
});
